# ═══════════════════════════════════════════════════════════════════════════════
#  DETECCIÓN DE HARDWARE Y DISCOS
# ═══════════════════════════════════════════════════════════════════════════════

def _ejecutar(cmd: list[str], timeout: int = 30) -> tuple[int, str, str]:
    try:
        r = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout)
        return r.returncode, r.stdout.strip(), r.stderr.strip()
    except FileNotFoundError:
        return -1, "", f"No encontrado: {cmd[0]}"
    except subprocess.TimeoutExpired:
        return -2, "", "Timeout"
    except Exception as e:
        return -3, "", str(e)


def detectar_disco_arranque() -> str:
    rc, out, _ = _ejecutar(["findmnt", "-n", "-o", "SOURCE", "/"])
    if rc == 0 and out:
        dev = out.strip().removeprefix("/dev/")
        return re.sub(r'p?\d+$', '', dev)
    rc, out, _ = _ejecutar(["lsblk", "-J", "-o", "NAME,MOUNTPOINTS"])
    if rc == 0 and out:
        try:
            for disco in json.loads(out).get("blockdevices", []):
                if _disco_tiene_mount(disco, "/"):
                    return disco["name"]
        except json.JSONDecodeError:
            pass
    try:
        with open("/proc/mounts") as f:
            for linea in f:
                partes = linea.split()
                if len(partes) >= 2 and partes[1] == "/":
                    return re.sub(r'p?\d+$', '', partes[0].removeprefix("/dev/"))
    except OSError:
        pass
    return ""


def _disco_tiene_mount(nodo: dict, punto: str) -> bool:
    mps = nodo.get("mountpoints") or [nodo.get("mountpoint")]
    if punto in (mps or []):
        return True
    for hijo in nodo.get("children", []):
        if _disco_tiene_mount(hijo, punto):
            return True
    return False


def listar_discos() -> list[dict]:
    rc, out, _ = _ejecutar([
        "lsblk", "-J", "-b", "-o", "NAME,SIZE,TYPE,MOUNTPOINTS,MODEL,TRAN,ROTA,VENDOR"
    ])
    if rc != 0 or not out:
        return []
    try:
        datos = json.loads(out)
    except json.JSONDecodeError:
        return []
    disco_arranque = detectar_disco_arranque()
    discos = []
    for nodo in datos.get("blockdevices", []):
        if nodo.get("type") != "disk":
            continue
        nombre = nodo.get("name", "")
        size_b = int(nodo.get("size") or 0)
        model  = (nodo.get("model") or nodo.get("vendor") or "").strip()
        tran   = (nodo.get("tran") or "").strip()
        rota   = nodo.get("rota") in ("1", True, 1)
        parts  = []
        for hijo in nodo.get("children", []):
            if hijo.get("type") in ("part", "lvm"):
                mps = hijo.get("mountpoints") or [hijo.get("mountpoint")]
                parts.append({
                    "name":   hijo.get("name", ""),
                    "size_b": int(hijo.get("size") or 0),
                    "mounts": [m for m in mps if m],
                })
        discos.append({
            "name":        nombre,
            "size_b":      size_b,
            "size_human":  _bytes_a_human(size_b),
            "model":       model or "Disco desconocido",
            "tran":        tran.upper() if tran else "—",
            "tipo":        "HDD" if rota else "SSD/NVMe",
            "es_arranque": (nombre == disco_arranque),
            "particiones": parts,
            "montajes":    _montes_activos(nodo),
        })
    return discos


def _montes_activos(nodo: dict) -> list[str]:
    result = []
    mps = nodo.get("mountpoints") or [nodo.get("mountpoint")]
    result.extend([m for m in (mps or []) if m])
    for hijo in nodo.get("children", []):
        result.extend(_montes_activos(hijo))
    return result


def _bytes_a_human(b: int) -> str:
    fb = float(b)
    for unit in ("B", "KB", "MB", "GB", "TB"):
        if fb < 1024.0:
            return f"{fb:.1f} {unit}"
        fb /= 1024.0
    return f"{fb:.1f} PB"


def es_uefi() -> bool:
    return Path("/sys/firmware/efi").exists()


def detectar_microcode() -> str:
    try:
        with open("/proc/cpuinfo") as f:
            c = f.read().lower()
        if "genuineintel" in c or "intel" in c:
            return "intel-ucode"
    except OSError:
        pass
    return "amd-ucode"


def verificar_internet() -> bool:
    rc, _, _ = _ejecutar(["ping", "-c", "1", "-W", "3", "8.8.8.8"], timeout=6)
    return rc == 0


def verificar_herramientas() -> dict[str, bool]:
    tools = ["parted", "mkfs.fat", "mkfs.ext4", "arch-chroot",
             "pacstrap", "genfstab", "mount", "umount"]
    return {h: shutil.which(h) is not None for h in tools}


